files.content:
:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --water: #4fc3f7;
  --water-dark: #0288d1;
  --success: #66bb6a;
  --border: #2a2a4a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  background-image: radial-gradient(circle at 20% 30%, #1f1f3a 0%, transparent 60%),
                    radial-gradient(circle at 80% 70%, #1a1a2e 0%, transparent 60%);
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  image-rendering: pixelated;
  text-align: center;
}

h1 {
  font-size: 28px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--water);
  margin-bottom: 8px;
  text-shadow: 2px 2px 0 #000;
}

.subtitle {
  font-size: 16px;
  color: #a0a0c0;
  margin-bottom: 24px;
}

.glass-display {
  font-size: 24px;
  font-weight: bold;
  margin-bottom: 16px;
  letter-spacing: 1px;
}

#glassCount {
  color: var(--water);
  font-size: 32px;
}

#goalCount {
  color: var(--accent);
}

.progress-container {
  width: 100%;
  height: 28px;
  background: var(--primary);
  border: 3px solid var(--border);
  margin-bottom: 20px;
  overflow: hidden;
  position: relative;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: repeating-linear-gradient(
    90deg,
    var(--water) 0px,
    var(--water) 8px,
    var(--water-dark) 8px,
    var(--water-dark) 16px
  );
  transition: width 0.3s steps(8);
}

.goal-message {
  font-size: 20px;
  font-weight: bold;
  color: var(--success);
  margin-bottom: 16px;
  padding: 12px;
  border: 3px dashed var(--success);
  background: rgba(102, 187, 106, 0.1);
  animation: pop 0.3s ease-out;
}

@keyframes pop {
  0% { transform: scale(0.8); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn {
  font-family: inherit;
  font-size: 18px;
  font-weight: bold;
  padding: 14px 20px;
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, background 0.15s;
  text-transform: uppercase;
  letter-spacing: 1px;
  min-width: 120px;
}

.btn.add {
  background: var(--water);
  color: #001a2e;
}

.btn.add:hover {
  background: #7fd8ff;
}

.btn.remove {
  background: var(--accent);
  color: #fff;
}

.btn.remove:hover {
  background: #ff6b81;
}

.btn:active {
  transform: translate(3px, 3px);
  box-shadow: none;
}

.btn:focus-visible {
  outline: 4px solid #fff;
  outline-offset: 2px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.hint {
  font-size: 16px;
  color: #8888aa;
  margin-bottom: 8px;
}

.goal-label {
  display: block;
  font-size: 16px;
  margin-bottom: 6px;
  color: #a0a0c0;
}

#goalInput {
  font-family: inherit;
  font-size: 18px;
  width: 80px;
  padding: 8px;
  text-align: center;
  background: var(--primary);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 0;
}

#goalInput:focus-visible {
  outline: 4px solid #fff;
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  .btn {
    padding: 12px 14px;
    font-size: 16px;
    min-width: 100px;
  }
  h1 {
    font-size: 22px;
  }
}

const state = {
  glasses: 0,
  goal: 8
};

const glassCountEl = document.getElementById('glassCount');
const goalCountEl = document.getElementById('goalCount');
const progressFill = document.getElementById('progressFill');
const progressBar = document.querySelector('.progress-container');
const goalMessage = document.getElementById('goalMessage');
const addBtn = document.getElementById('addBtn');
const removeBtn = document.getElementById('removeBtn');
const goalInput = document.getElementById('goalInput');

function updateUI() {
  glassCountEl.textContent = state.glasses;
  goalCountEl.textContent = state.goal;

  const percent = Math.min((state.glasses / state.goal) * 100, 100);
  progressFill.style.width = percent + '%';

  progressBar.setAttribute('aria-valuemax', state.goal);
  progressBar.setAttribute('aria-valuenow', state.glasses);

  if (state.glasses >= state.goal) {
    goalMessage.hidden = false;
  } else {
    goalMessage.hidden = true;
  }

  removeBtn.disabled = state.glasses <= 0;
}

function addGlass() {
  state.glasses++;
  updateUI();
}

function removeGlass() {
  if (state.glasses > 0) {
    state.glasses--;
    updateUI();
  }
}

function setGoal(value) {
  const newGoal = Math.max(1, Math.min(20, parseInt(value, 10) || 8));
  state.goal = newGoal;
  goalInput.value = newGoal;
  updateUI();
}

addBtn.addEventListener('click', addGlass);
removeBtn.addEventListener('click', removeGlass);

goalInput.addEventListener('change', (e) => {
  setGoal(e.target.value);
});

goalInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    setGoal(e.target.value);
  }
});

updateUI();
